    /// <summary>
    /// One higher-tier character as plain data (docs/34): which hero line it belongs to, its own id, name and art, and its run bonus on top of the Common hero. Its four physics numbers are the absolute row of the line and tier in <see cref="HeroTable"/>.
    /// A new hero is one row here, its rows in HeroTable (generated by Tools/hero_table_gen.py) and art in Resources/Characters/id.
    /// </summary>
    public sealed class TierRow
    {
        public string LineId;
        public string Id;
        public string Name;
        public CharacterRarity Rarity;
        /// <summary>
        /// Art slot: the pictures live in Resources/Characters/{Id}/ (same part files and rig.json as the Common hero). Until that folder exists the game draws the
        /// line's Common hero instead, tinted, so the tier is visible as a placeholder. Dropping the real art into the folder swaps it with no code change.
        /// </summary>
        public string ArtId;
        /// <summary>Added to the Common hero's own end-of-run bonus (docs/44): coins in multiples of 10, gems in ones, inside the tier rule's range.</summary>
        public int RunCoinsAdd, RunGemsAdd;
    }

