        /// <summary>Builds the specs of all rows whose line has a Common hero among <paramref name="bases"/>. Each tier hero takes its ABSOLUTE physics from <see cref="HeroTable"/> (no chain, no percent).</summary>
        public static CharacterSpec[] Create(IList<CharacterSpec> bases)
        {
            var list = new List<CharacterSpec>(Rows.Length);
            foreach (TierRow row in Rows)
            {
                CharacterSpec b = null;
                foreach (CharacterSpec c in bases) if (c.Id == row.LineId) { b = c; break; }
                if (b == null) continue;
                HeroRow hr = HeroTable.Find(row.Id);
                if (hr == null) continue;
                CharacterStats common = b.Stats ?? CharacterStats.Default;
                CharacterStats stats = Cap(new CharacterStats
                {
                    JumpLaunchTenths = hr.LaunchTenths,
                    MaxSpeed = hr.Speed,
                    Control = hr.Control,
                    WallBoostHundredths = hr.Wall,
                    CoinFind = common.CoinFind,
                    GemFind = common.GemFind,
                    RunBonusCoins = common.RunBonusCoins + row.RunCoinsAdd,
                    RunBonusGems = common.RunBonusGems + row.RunGemsAdd,
                });
                list.Add(new CharacterSpec
                {
                    Id = row.Id,
                    Name = row.Name,
                    Rarity = row.Rarity,
                    Region = 0,
                    Line = row.LineId,
                    ArtId = row.ArtId,
                    FallbackArtId = b.FallbackArtId ?? b.Id,
                    IsMergeTier = true,
                    Powers = TierRules.PowersFor(row.LineId, row.Rarity),
                    Shown = ShownStats.From(stats, new SimConfig()),
                    Stats = stats,
                });
            }
            return list.ToArray();
        }

        /// <summary>
        /// The effective stats: the four physics stats clamped to the documented safe limits (docs/44 section 4, launch in tenths) as a safety net so every level stays solvable. The generated table rows are
        /// inside the limits already (a test checks it), so this changes nothing for them. The run bonus (meta only, never in the simulation) is kept in full.
        /// </summary>
        public static CharacterStats Cap(CharacterStats d)
        {
            int tenths = Clamp(d.LaunchTenths, CharacterStats.JumpLaunchMinTenths, CharacterStats.JumpLaunchMaxTenths);
            return new CharacterStats
            {
                JumpLaunch = tenths / 10,
                JumpLaunchTenths = tenths,
                MaxSpeed = Clamp(d.MaxSpeed, CharacterStats.MaxSpeedMin, CharacterStats.MaxSpeedMax),
                Control = Clamp(d.Control, CharacterStats.ControlMin, CharacterStats.ControlMax),
                WallBoostHundredths = Clamp(d.WallBoostHundredths, CharacterStats.WallBoostMin, CharacterStats.WallBoostMax),
                CoinFind = Clamp(d.CoinFind, 0, CharacterStats.CoinFindMax),
                GemFind = Clamp(d.GemFind, 0, CharacterStats.GemFindMax),
                RunBonusCoins = d.RunBonusCoins,
                RunBonusGems = d.RunBonusGems,
            };
        }

        static int Clamp(int v, int lo, int hi) { return v < lo ? lo : (v > hi ? hi : v); }
    }
}
